static const char* AGENT_TOOLS_JSON = R"PMSTOOLS([{"name":"get_project","description":"Returns project state. Slim by default: {duration, fps, bpm, audio_path, project_path, transcript_ready, playhead, tracks: [{index, name, muted, locked, clip_count}], markers}. Use verbose=true for full clip details (all styling, FX props). Prefer get_clips(track_name=...) when you only need clip positions on one track. Read-only — no batch needed.","inputSchema":{"type":"object","properties":{"verbose":{"type":"boolean","description":"Return full clip details (default false)"}}},"ipc":true},{"name":"get_clips","description":"Return the clips on one track: [{index, type, start, end, duration, in_point, source, text}]. Use this instead of get_project when you only need clip positions on a specific track — much smaller response. Accepts track index or track_name. Read-only — no batch needed.","inputSchema":{"type":"object","properties":{"track":{"type":"integer"},"track_name":{"type":"string","description":"Track name (alternative to track index)"}}},"ipc":true},{"name":"get_all_clips","description":"Return clips across ALL tracks: [{index, name, clips: [{index, type, start, end, duration, in_point, source, text}]}]. Use for full-timeline orientation without get_project(verbose=true). Read-only — no batch needed.","inputSchema":{"type":"object","properties":{}},"ipc":true},{"name":"trigger_export","description":"Render and export the project to MP4 (or GIF). Blocks until complete — returns {done, success, output, stage} when finished. No batch needed.\n\noutput_path: override default path (defaults to {project_dir}/{name}.mp4).\ncrf: quality 0–51, lower = better (default 23).\npreset: ultrafast|fast|medium|slow (default medium).\ngif: true to export animated GIF instead of MP4.","inputSchema":{"type":"object","properties":{"output_path":{"type":"string","description":"Override output file path"},"crf":{"type":"integer","description":"Quality 0–51 (default 23)"},"preset":{"type":"string","enum":["ultrafast","fast","medium","slow"]},"gif":{"type":"boolean","description":"Export GIF instead of MP4"}}},"ipc":true},{"name":"get_export_status","description":"Poll export progress. Returns {running, progress (0–1), frame, total_frames, eta_secs, stage, output}. Read-only — no batch needed.","inputSchema":{"type":"object","properties":{}},"ipc":true},{"name":"cancel_export","description":"Cancel a running export. No batch needed.","inputSchema":{"type":"object","properties":{}},"ipc":true},{"name":"cancel_search","description":"Cancel a running find_and_add_clip / search_transcript operation. Safe to call even if no search is running. No batch needed.","inputSchema":{"type":"object","properties":{}},"ipc":true},{"name":"get_stills","description":"Generate and return thumbnail images for a list of media files so you can visually identify their content before deciding which to add to the timeline.\n\nFor each path: if a still already exists on disk it is returned instantly; otherwise a quarter-resolution JPEG is extracted via ffmpeg (< 1 s per file). The full proxy transcode is NOT started — this is purely for identification.\n\nReturns one inline image per file. Files that fail to produce a still are included in the result with ok=false and no image.\n\nRead-only — no batch needed.","inputSchema":{"type":"object","properties":{"paths":{"type":"array","items":{"type":"string"},"description":"Absolute paths to media files (video, image, or audio with cover art)"}},"required":["paths"]},"ipc":true},{"name":"get_media_info","description":"Probe a media file and return its codec/format metadata: duration (seconds), width, height, fps, has_video, has_audio, video_codec, audio_codec, sample_rate, channels. Use this to diagnose audio/video stream issues before adding a clip. Read-only — no batch needed.","inputSchema":{"type":"object","properties":{"path":{"type":"string","description":"Absolute path to the media file"}},"required":["path"]},"ipc":true},{"name":"list_dir","description":"List the files and subfolders in a directory. Use this to DISCOVER media on disk instead of guessing paths or probing files one by one. Accepts a folder path, OR a file path (lists the folder that contains it — handy when you only have an audio/video path).\n\nReturns {dir, entries, n_dirs, n_files, truncated?}. Each entry is {name, path, is_dir, kind, ext, size_bytes}; kind is video|audio|image|other|dir. Subfolders are listed first so you can navigate into them.\n\nkind: filter results — 'all' (default), 'media' (video+audio+image), 'video', 'audio', or 'image'. To find mp4s/movies in a folder, pass kind='video'.\nrecursive: when true, walks subfolders (depth-capped; max 1000 entries, then truncated=true). Default false (shallow). Hidden/dotfiles are skipped. Read-only — no batch needed.","inputSchema":{"type":"object","properties":{"path":{"type":"string","description":"Absolute path to a folder (or a file, to list its folder)"},"kind":{"type":"string","default":"all","description":"all | media | video | audio | image"},"recursive":{"type":"boolean","default":false,"description":"Walk subfolders (depth-capped)"}},"required":["path"]},"ipc":true},{"name":"crop_media","description":"Reframe a video/image to a target aspect ratio. NON-DESTRUCTIVE by default: computes the crop box (with face detection) and applies it as the clip's crop_l/crop_t/crop_r/crop_b props — NO file is written and the engine composites the crop live. If the source is already on the timeline it sets the crop on those clips; otherwise it returns the insets for you to set after add_clip.\n\naspect: 'square' (1:1), 'vertical' (9:16), 'horizontal' (16:9), or 'W:H'.\nface_detect (default true): auto-detect the face box and center the crop on it.\nx_pct / y_pct: manual center when face_detect=false (0.5/0.5 = dead center).\npad_top / pad_bottom: padding around the face (fraction of face height).\nto_file (default false): set true ONLY when you genuinely need a cropped FILE on disk (re-encodes a {stem}_crop.{mp4,png}). Leave false for editing — it litters and is destructive.\n\nReturns {mode:'clip_props', crop_l..crop_b, applied_to, face_detected} (default) or {path, ...} (to_file) plus an inline thumbnail. Supports HEIC/JPG/PNG and MOV/MP4 etc. Read-only — no batch needed.","inputSchema":{"type":"object","properties":{"source_path":{"type":"string","description":"Absolute path to source file"},"aspect":{"type":"string","default":"square","description":"square | vertical | horizontal | W:H"},"face_detect":{"type":"boolean","default":true,"description":"Auto-detect face and center crop on it"},"pad_top":{"type":"number","default":0.4,"description":"Padding above face as fraction of face height"},"pad_bottom":{"type":"number","default":0.3,"description":"Padding below face as fraction of face height"},"x_pct":{"type":"number","default":0.5,"description":"Horizontal center of crop (0=left, 1=right) — used when face_detect=false"},"y_pct":{"type":"number","default":0.5,"description":"Vertical center of crop (0=top, 1=bottom) — used when face_detect=false"},"to_file":{"type":"boolean","default":false,"description":"Render a cropped FILE instead of setting clip crop props (destructive; default false)"}},"required":["source_path"]},"ipc":false},{"name":"get_search_status","description":"Poll a running transcript search started by find_and_add_clip. Returns: running (bool), progress (0–1), message, found (bool), start (seconds), end (seconds), excerpt, error.\n\nCall every 3s until running=false. Print message each poll so the user sees progress. When done: if found=true, the matched segment has already been extracted and added to the timeline.","inputSchema":{"type":"object","properties":{}},"ipc":true},{"name":"get_pipeline_status","description":"Returns the current ML pipeline status: stage (idle/extract/transcribe/align/done/error), progress (0–1), message, and error string. trigger_pipeline returns immediately with stage='running' — poll this every 2–3s until stage='done' (or 'error'). No batch needed.","inputSchema":{"type":"object","properties":{}},"ipc":true},{"name":"begin_batch","description":"Group multiple mutations into one undo step.\n\nYOU PROBABLY DON'T NEED THIS for a single mutation. The server auto-batches every individual mutation call (add_clip, set_clip_prop, add_track, delete_clip, add_effect_brick, etc.) using the method name as the undo label, so a one-off set_clip_prop on its own becomes one undo step automatically.\n\nUSE begin_batch when you want a SEQUENCE of mutations to undo as a single step — e.g. add_track + add_clip + set_clip_prop to set up a clip in one motion, or a loop of set_clip_prop calls applying a style to many clips. Pass a descriptive label that reads well in the undo menu (\"Set up intro lyrics\", \"Apply karaoke preset\").\n\nBatches can't be nested. Always pair with end_batch — if the connection drops mid-batch the in-flight changes are saved as \"<label> (incomplete)\" so nothing is lost.","inputSchema":{"type":"object","properties":{"label":{"type":"string","description":"Undo history label"}},"required":["label"]},"ipc":true},{"name":"end_batch","description":"Commit the current edit batch to the undo history.","inputSchema":{"type":"object","properties":{}},"ipc":true},{"name":"add_to_bin","description":"Add a media file to the project Bin. The Bin is the project-scoped media library shown in the right-side panel — files here are 'available to use' but are not on the timeline yet. The user (or you, via add_clip) drags from the Bin onto a track to actually place them.\n\nWhen to call this:\n  - You discovered several candidate files and want to surface them to the user without committing placements yet.\n  - The user said something like 'have a look at these clips' or 'find me good options' — load them into the Bin, then ask which to place.\n  - You're processing a batch import (extracted segments, cropped variants) where not every file will end up on the timeline.\n\nWhen NOT to call this: don't call it before every add_clip. add_clip on a video/audio path automatically mirrors the file into the Bin, so for direct placements just call add_clip and skip this. No batch needed.","inputSchema":{"type":"object","properties":{"path":{"type":"string","description":"Absolute path to a media file"}},"required":["path"]},"ipc":true},{"name":"remove_from_bin","description":"Remove a media file from the project Bin. Does NOT remove clips already placed on the timeline that reference the file — those keep working (the timeline holds its own path reference). Use delete_clip first if you also want to remove its placements. No batch needed.","inputSchema":{"type":"object","properties":{"path":{"type":"string","description":"Absolute path of the bin entry to remove"}},"required":["path"]},"ipc":true},{"name":"add_clip","description":"Place a clip on a track.\n\nBIN vs TIMELINE: add_to_bin makes a media file 'available to the project' (shows in the Bin panel). add_clip actually places it on the timeline. Use add_to_bin when you've discovered files the user might want but you're not sure yet; use add_clip when you're committing to a placement. add_clip on a video/audio path automatically also adds the file to the bin, so you don't need both calls for files you're placing right away.\n\ntype: video | audio | text | lyrics | subtitle | effect | background | body_fx | record\neffect/body_fx bricks cannot overlap another FX brick on the same track — rejected; layer effects with add_multifx_brick instead.\nNO OVERLAP: content/text clips (video, audio, text, lyrics, subtitle, background) cannot overlap another clip on the same track — rejected. Clips on one track are sequential; for simultaneous clips put them on separate tracks. Frame-adjacent (one clip ends where the next starts) is fine.\ntype='record' is a loop-record brick: the user records mic takes over its range in the app (agents cannot record). Its 'takes' (WAV paths) and 'selected_take' appear in get_project/get_clips; the selected take plays in preview and export. Switch takes with set_clip_prop(prop='selected_take'); place a take as a normal audio clip with add_clip type='audio' text=<take path>.\nFor video files (.mp4 .mov .webm etc): type='video', text=absolute path.\nFor audio-only files (.flac .mp3 .wav .ogg etc): type='audio', text=absolute path. NEVER use type='video' for audio-only files — it will fail with 'cannot write output header'.\nImages & GIFs (PNG/JPG/WEBP/HEIC/GIF): type='video', text=absolute path — place the file DIRECTLY. Do NOT convert it to a video first (that was the old flow and is no longer needed). Stills render at full quality with transparency preserved; a GIF animates and loops to fill the clip's span. Set 'end' for how long it shows (defaults to start+2s). Reframe with the crop/pos/scale props.\n\nTEXT CLIPS — read this before adding any:\n  For LYRICS / CAPTIONS / KARAOKE: do NOT hand-build clips here. Call trigger_pipeline (it transcribes and lays styled lyric bricks for you), then optionally set_typography_preset (preset=...) to swap the visual style. type='lyrics' clips placed here will render with default positioning that may be off-canvas and won't follow the global typography preset.\n  For a SINGLE LABELED CALLOUT (label an object, person, action on screen): use add_callout instead — it sets correct positioning and gives you an arrow option.\n  type='text' is only for genuine one-off text not covered by the above. If you do use it, you MUST set sub_pos_x (0.5 = center) and font_size via set_clip_prop or the text will render off-canvas.\n\nBACKGROUND CLIPS — type='background', text = a preset id (REQUIRED — the call fails without a valid one). Preset ids: solid, blob, lava, aurora, plasma, oilslick, inkdrop, gradsweep, sunset, neonflood, colorpulse, spotlight, prism, gridpulse, stripes, rings, tunnel, vwgrid, checker, hex, halftone, filmgrain, tvstatic, crt, vhstracking, glitchblk, matrix, starfield, rain, snow, confetti, bubbles, fire, waveform, ripple, breathing, clocksweep, noisedrift, lightning.\n  For a FLAT COLOR: text='solid', then set_clip_prop bg_c1=[r,g,b,a] (defaults to white). Animated presets take up to three colors (bg_c1..bg_c3) plus bg_speed/bg_intensity — sensible defaults are applied from the preset. Place backgrounds on a high-index track so they sit behind your content.\n\nFRAME SNAPPING — start/end always snap to the project's frame grid (1/fps seconds). The engine rounds start to the nearest frame and rounds end UP. If you place clips back-to-back by passing next.start = prev.end (your intended values), the snapped previous-end may push one frame past your intended next.start, causing an overlap error. RECOVERY: read the error message — it includes the colliding clip's snapped end (e.g. \"[90.100s – 90.767s]\"). Use that snapped end as the next clip's start. Better: call get_clips after each add and use the returned 'end' field as the next clip's start.\n\nDerived artifacts (transcripts, stems, extracted segments) live in a shared cache dir (~/.cache/pop-maker-studio), NOT next to the user's media — don't construct or rely on sidecar paths. To reframe/crop, set clip props (crop_l/crop_t/crop_r/crop_b, pos, scale) — it's non-destructive and writes no file; crop_media (which renders a new file) is only for an explicit on-disk crop.","inputSchema":{"type":"object","properties":{"quiet":{"type":"boolean","description":"Return a small ack instead of the full project state (big token saver — use unless you need to re-read state)"},"track":{"type":"integer"},"track_name":{"type":"string","description":"Track name (alternative to track index)"},"type":{"type":"string"},"start":{"type":"number"},"end":{"type":"number"},"text":{"type":"string","default":""}},"required":["type","start","end"]},"ipc":true},{"name":"add_track","description":"Add a track at position (0=top/foreground, higher=background). Returns track index.\n\nLAYERING RULE: track 0 = top (foreground). Highest index = bottom (background).\n  Text, FX, overlays → low-index tracks (0, 1, 2…)\n  Video, background  → high-index tracks","inputSchema":{"type":"object","properties":{"quiet":{"type":"boolean","description":"Return a small ack instead of the full project state (big token saver — use unless you need to re-read state)"},"name":{"type":"string","description":"Track name"},"position":{"type":"integer","description":"Insert position (0 = top)","default":0}}},"ipc":true},{"name":"delete_clip","description":"Delete a clip.","inputSchema":{"type":"object","properties":{"quiet":{"type":"boolean","description":"Return a small ack instead of the full project state (big token saver — use unless you need to re-read state)"},"track":{"type":"integer"},"track_name":{"type":"string","description":"Track name (alternative to track index)"},"clip":{"type":"integer"}},"required":["clip"]},"ipc":true},{"name":"move_clip","description":"Move a clip to a new start time (preserves duration). Moving an FX brick onto another FX brick's time range on the same track is rejected — FX bricks never overlap (use add_multifx_brick to combine effects).","inputSchema":{"type":"object","properties":{"quiet":{"type":"boolean","description":"Return a small ack instead of the full project state (big token saver — use unless you need to re-read state)"},"track":{"type":"integer"},"track_name":{"type":"string","description":"Track name (alternative to track index)"},"clip":{"type":"integer"},"start":{"type":"number"}},"required":["clip","start"]},"ipc":true},{"name":"trim_clip","description":"Trim a clip's start and/or end time. Trimming an FX brick so it would lap another FX brick on the same track is rejected — FX bricks never overlap.","inputSchema":{"type":"object","properties":{"quiet":{"type":"boolean","description":"Return a small ack instead of the full project state (big token saver — use unless you need to re-read state)"},"track":{"type":"integer"},"track_name":{"type":"string","description":"Track name (alternative to track index)"},"clip":{"type":"integer"},"start":{"type":"number"},"end":{"type":"number"}},"required":["clip"]},"ipc":true},{"name":"split_clip","description":"Split a clip at one or more time points. Pass times=[...] to make every cut in one call — never loop split_clip for a multi-cut edit. Returns left_clip/right_clip for a single cut, plus clips (all resulting indices, leftmost first) for multiple cuts.","inputSchema":{"type":"object","properties":{"quiet":{"type":"boolean","description":"Return a small ack instead of the full project state (big token saver — use unless you need to re-read state)"},"track":{"type":"integer"},"track_name":{"type":"string","description":"Track name (alternative to track index)"},"clip":{"type":"integer"},"time":{"type":"number","description":"Single cut point (seconds)"},"times":{"type":"array","items":{"type":"number"},"description":"Multiple cut points (seconds); all must fall inside the clip"}},"required":["clip"]},"ipc":true},{"name":"set_clip_prop","description":"Set one property on a clip.\n\nLAYOUT:    pos_x, pos_y (0–1 canvas fraction), scale_x, scale_y, rotation\nFLIP:      flip_h, flip_v (bool) — MIRROR the content (face the other way /\n           upside-down). Use these, NOT a negative scale_x/scale_y: negative\n           scale mirrors AND resizes (e.g. -0.1 shrinks to 10%).\nCROP:      crop_l, crop_t, crop_r, crop_b (0–0.95 fraction trimmed per side,\n           display orientation). Non-destructive render-time UV window —\n           prefer this over crop_media when the media is already on the\n           timeline; the fit box follows the cropped aspect.\nPLAYBACK:  volume (0–2), speed (0.25–100; retimes like the UI — the clip's\n           timeline width rescales to keep the same source span, and FX\n           bricks riding the clip rescale with it. Downstream clips do NOT\n           ripple: a shrunk clip leaves a gap — close it with move_clip.\n           Pass retime=false to keep start/end and change which source\n           range plays instead), opacity (0–1), muted (bool),\n           fade_in, fade_out\n           (in_point is NOT settable — trim the brick with trim_clip, like the UI)\nTEXT:      text, font_size (0=auto), sub_pos (0=bottom 1=center 2=top 3=custom),\n           sub_pos_x/y (0–1), sub_anchor_h (0=left 1=center 2=right),\n           sub_wrap_w (0–1), sub_color ([r,g,b,a] 0–1)\nANIMATION: clip_style (none|fade|glitch|typewriter|bounce|scale|slide|stack|block),\n           blend_mode (normal|add|multiply|screen|overlay)\nRECORD:    selected_take (int index into the record brick's takes; -1 = none)\nFACE:      face_filter (camera bricks: 0=None 1=Pretty 2=BigEyes 3=TinyFace\n           4=BigMouth 5=Alien 6=Doggy — live mirror + takes/export via cached\n           landmark pass), face_filter_amt (0–1.5 strength)\nCOLOR GRADE (video clips only):\n           grade_brightness (-1–1), grade_contrast (0–3),\n           grade_saturation (0–3), grade_hue (-180–180)\nBACKGROUND (background clips only):\n           bg_c1, bg_c2, bg_c3 ([r,g,b,a] 0–1 — 'solid' uses bg_c1 only;\n           animated presets use up to all three), bg_speed, bg_intensity (0–1)\nAUDIO SYNC: To sync audio to a video at a specific source moment, use a negative\n           clip start: start = -source_timestamp, end = video_duration - source_timestamp","inputSchema":{"type":"object","properties":{"quiet":{"type":"boolean","description":"Return a small ack instead of the full project state (big token saver — use unless you need to re-read state)"},"track":{"type":"integer"},"track_name":{"type":"string","description":"Track name (alternative to track index)"},"clip":{"type":"integer"},"prop":{"type":"string"},"value":{},"retime":{"type":"boolean","description":"speed only: false keeps the clip's start/end instead of rescaling its timeline width (default true)"}},"required":["clip","prop","value"]},"ipc":true},{"name":"set_clip_keyframes","description":"Replace the keyframe track for one animatable property on a clip — this is how you animate position, scale, rotation, opacity, volume, pan, or a video FX brick's Amount over time. Keyframable props: pos_x, pos_y, scale_x, scale_y, rotation, opacity, volume, pan; on a video FX brick, amount (rides its Amount slider); plus per-effect fields like fx_brightness, fx_contrast, fx_blur, fx_<effect>_amount.\n\nkeys: full list of {t, v, interp?} replacing any existing keys for that prop. t is SECONDS RELATIVE TO CLIP START; interp is the easing toward the NEXT key: linear | ease_in | ease_out | ease_both (default) | hold. Pass keys=[] to clear the track (the static property value takes over again). While keys exist the static field for that prop is ignored.\n\nKeys render in both preview and export, survive split/trim (remapped), and show as diamonds on the clip in the timeline. Existing keyframes appear under 'keyframes' on each clip in get_project(verbose=true).","inputSchema":{"type":"object","properties":{"quiet":{"type":"boolean","description":"Return a small ack instead of the full project state (big token saver — use unless you need to re-read state)"},"track":{"type":"integer"},"track_name":{"type":"string","description":"Track name (alternative to track index)"},"clip":{"type":"integer"},"prop":{"type":"string","description":"pos_x | pos_y | scale_x | scale_y | rotation | opacity | volume | pan | amount (a video FX brick's Amount slider) | fx_<effect>_amount | fx_brightness | fx_contrast | fx_blur | ..."},"keys":{"type":"array","items":{"type":"object","properties":{"t":{"type":"number","description":"Seconds relative to clip start"},"v":{"type":"number"},"interp":{"type":"string","description":"linear|ease_in|ease_out|ease_both|hold (easing toward next key)"}},"required":["t","v"]}}},"required":["clip","prop","keys"]},"ipc":true},{"name":"add_clip_sequence","description":"Add multiple clips to a single track in one round-trip. Equivalent to calling add_clip N times but dramatically faster for beat-sync edits or any bulk layout. Returns an array of assigned clip IDs in order.\n\nEach entry in 'clips': {type, start, end, text (file path for video/audio)}","inputSchema":{"type":"object","properties":{"quiet":{"type":"boolean","description":"Return a small ack instead of the full project state (big token saver — use unless you need to re-read state)"},"track":{"type":"integer"},"clips":{"type":"array","items":{"type":"object","properties":{"type":{"type":"string"},"start":{"type":"number"},"end":{"type":"number"},"text":{"type":"string","default":""}},"required":["type","start","end"]}}},"required":["track","clips"]},"ipc":true},{"name":"set_clip_props","description":"Set properties on multiple clips in one call. ops: [{track, clip, prop, value}]. Setting speed retimes like the UI (clip width rescales; see set_clip_prop) — per-op retime=false opts out.","inputSchema":{"type":"object","properties":{"quiet":{"type":"boolean","description":"Return a small ack instead of the full project state (big token saver — use unless you need to re-read state)"},"ops":{"type":"array","items":{"type":"object","properties":{"track":{"type":"integer"},"clip":{"type":"integer"},"prop":{"type":"string"},"value":{},"retime":{"type":"boolean","description":"speed only: false keeps start/end instead of rescaling timeline width (default true)"}},"required":["track","clip","prop","value"]}}},"required":["ops"]},"ipc":true},{"name":"set_text_style","description":"Set visual text styling on a clip. All fields are optional — only provided fields are updated. Color arrays are [r, g, b, a] with values 0–1.\nFields: shadow_enabled (bool), shadow_ox, shadow_oy, shadow_col,\n  stroke_enabled, stroke_w, stroke_col,\n  glow_enabled, glow_r, glow_col,\n  bg_enabled, bg_col, bg_pad_x, bg_pad_y, bg_corner\n\nWARNING — do NOT call this on lyrics/subtitle clips generated by trigger_pipeline. Those clips inherit style from the global preset; overriding a single clip detaches it from the global system and produces inconsistent results. If the user wants a different text style, call set_typography_preset with the preset that best matches their request — the preset IS the style. Only use set_text_style on individual text clips (type='text') when the user explicitly asks for a per-clip override.","inputSchema":{"type":"object","properties":{"quiet":{"type":"boolean","description":"Return a small ack instead of the full project state (big token saver — use unless you need to re-read state)"},"track":{"type":"integer"},"clip":{"type":"integer"},"shadow_enabled":{"type":"boolean"},"shadow_ox":{"type":"number"},"shadow_oy":{"type":"number"},"shadow_col":{"type":"array","items":{"type":"number"},"minItems":4,"maxItems":4},"stroke_enabled":{"type":"boolean"},"stroke_w":{"type":"number"},"stroke_col":{"type":"array","items":{"type":"number"},"minItems":4,"maxItems":4},"glow_enabled":{"type":"boolean"},"glow_r":{"type":"number"},"glow_col":{"type":"array","items":{"type":"number"},"minItems":4,"maxItems":4},"bg_enabled":{"type":"boolean"},"bg_col":{"type":"array","items":{"type":"number"},"minItems":4,"maxItems":4},"bg_pad_x":{"type":"number"},"bg_pad_y":{"type":"number"},"bg_corner":{"type":"number"}},"required":["track","clip"]},"ipc":true},{"name":"set_typography_preset","description":"ASSIGN a typography preset to the project's managed lyric bricks. The per-word/phrase lyric bricks come from trigger_pipeline (they live on a managed 'Lyrics' track); this tool sets the STYLE they render in — it does not transcribe or hand-build text. Idempotent: re-assign any time to swap the look (clears the lyric clips for the current audio and re-lays them in the new preset). If a transcript is ready but no lyric bricks exist yet, assigning a preset lays them in that style.\n\nYou usually don't need this right after trigger_pipeline — the pipeline already lays the bricks in the preset you passed it. Reach for this to CHANGE the preset.\n\nPRESET SYSTEM: each preset bundles grouping, position, animation, color, and optional FX clips. The preset IS the style — do NOT call set_text_style on the lyric clips afterward to tweak them; that breaks the global styling. Match the user's style request to the closest preset here and assign it. Karaoke is a preset — use preset='karaoke', do NOT set karaoke=true manually.\n\nINTERPRET, DON'T HAND-ROLL: if the user describes a style (e.g. 'bold white caps with drop shadow', 'tiktok one-word', 'spotify bottom bar'), map it to the closest preset below and assign it. Do NOT build text clips manually via add_clip(type='text') just because the user's wording doesn't match a preset name verbatim — the presets are deliberately broad and the closest fit is correct.\n\nPRESET GUIDE — pick based on user's style request:\n  flash      — ONE WORD · white · all-caps · hard cuts · no effects  ← TikTok lyric video default\n  strobe     — same as flash but inverts color every word · ultra aggressive\n  rave       — one word · neon pink · random positions · beat-reactive · chromatic aberration FX\n  cyberpunk  — 3 words · cyan · monospace · bottom-left · glitch FX\n  drill      — 3 words · yellow · top third · aggressive cuts\n  tumblr     — phrases · white · lowercase · centered · fade\n  indie2012  — lines · muted off-white · small · left offset · fade\n  sadgirl    — one word · pastel pink · large · centered · slow fade\n  cottagecore— lines · warm cream · centered · gentle fade · film grain FX\n  film       — lines · white · bottom subtitle style · classic fade\n  headline   — ONE WORD · white · all-caps · massive · scale animation\n  manifesto  — lines · white · all-caps · left flush · stacked · block anim\n  zine       — phrases · white · mixed case · glitch animation\n  newspaper  — segments · white · all-caps · tight centered block\n  minimal    — phrases · light grey · small · centered · fade · breathing room\n  spotify    — phrases · white · bottom center · clean · fade\n  apple      — ONE WORD · white · large · centered · smooth fade\n  kinetic    — phrases · white · centered · slides in from left\n  karaoke    — lines · grey → highlighted word · bottom · classic karaoke\n  vhs        — lines · white · bottom · VHS grain FX\n  neon       — one word · hot pink · glow · beat-reactive · centered\n  lofi       — phrases · warm · small · film grain FX · chill\n\nMATCHING EXAMPLES:\n  'one word at a time, bold white, no effects' → flash\n  'one word, white, big, clean fade' → apple\n  'one word, white, really massive fills frame' → headline\n  'tiktok style word by word' → flash\n  'spotify style' → spotify\n  'karaoke / word highlight' → karaoke\n  'aesthetic, pastel' → sadgirl\n  'retro, vhs' → vhs","inputSchema":{"type":"object","properties":{"preset":{"type":"string","description":"Typography preset id. One of: flash, strobe, rave, cyberpunk, drill, tumblr, indie2012, sadgirl, cottagecore, film, headline, manifesto, zine, newspaper, minimal, spotify, apple, kinetic, karaoke, vhs, neon, lofi. Defaults to the app's currently selected preset (spotify) if omitted."}}},"ipc":true},{"name":"trigger_pipeline","description":"Kick off the ML pipeline (MDX-Net + transcription) on the project audio. NON-BLOCKING: returns immediately with stage='running'. Poll get_pipeline_status every 2–3s until stage='done'. When the audio is a clip on the timeline, the lyric bricks are laid AUTOMATICALLY on completion — styled by `preset`, positioned to the brick — exactly like the UI's Generate Lyrics button. You do NOT need a separate set_typography_preset call to place them. RE-RUNNING after a trim or a preset change REUSES the cached transcript (no re-transcription — a trim never invalidates a source-relative transcript); it just re-lays the lyrics. Pass force=true to force a real re-run. No batch needed.\n\nFULL WORKFLOW:\n  1. add_track('Audio') + add_clip(type='audio', text=<path>) — put the song on the\n     timeline and trim the brick to its FINAL span before transcribing.\n  2. trigger_pipeline(mode='both', preset='flash')  → returns stage='running'\n  3. loop: get_pipeline_status() every 2–3s until stage='done' (or 'error'); the styled\n     lyric bricks are laid automatically when it finishes — no set_typography_preset needed.\n  4. (optional) set_typography_preset(preset='...') to swap the style, or to re-fit the\n     lyrics if you moved/trimmed the audio brick AFTER transcribing.\n\nPROBE FIRST: call get_transcript() — if status='ready' the transcript is already cached on disk. If lyric bricks are already on the timeline you can skip this entirely. Only call trigger_pipeline when no transcript exists for this audio.\n\nPIPELINE MODES:\n  both          — (default) MDX-Net (Kim_Vocal_2) stem separation → vocals.wav → transcription of the isolated vocal stem. ALWAYS separates first — it yields clean voices on any source (music, speech, noisy capture), so there is no raw-mix mode.\n  separate_only — Run MDX-Net only, no transcription. No bricks to lay afterward.\n\nPRESET QUICK-PICKS for step 4 (full list in set_typography_preset):\n  flash    — one word, white, all caps, hard cuts (TikTok default)\n  apple    — one word, white, large, smooth fade\n  spotify  — phrases, white, bottom center, clean fade\n  karaoke  — line with current word highlighted, bottom\n  headline — one word, massive, scale animation\n\nDO NOT use this to search for a specific moment — use find_and_add_clip instead (windowed search, much faster).\n\nNEVER run this on a full-length song/track when the user only wants a section. Instead: (1) find_and_add_clip(path=full_file, query='end phrase') — returns the exact end timestamp and adds the located clip; (2) add the song to the timeline and trim the audio brick to the section; (3) trigger_pipeline on that brick (it transcribes only the trimmed region). NEVER add padding beyond result.end — find_and_add_clip gives exact word-boundary timestamps.","inputSchema":{"type":"object","properties":{"mode":{"type":"string","enum":["both","separate_only"],"default":"both"},"path":{"type":"string","description":"Absolute path to media file. Transcribes this file without adding it to the timeline."},"preset":{"type":"string","description":"Typography preset for the lyric bricks laid automatically on completion (flash, apple, spotify, karaoke, headline, ...). Applied like the UI's Generate Lyrics. Omit to keep the current preset."},"force":{"type":"boolean","description":"Force a real re-run of separation+transcription even when a cached transcript already covers the brick. Default false: after trimming the brick or changing preset the cached transcript is reused and only the lyrics are re-laid (no re-transcription)."}}},"ipc":true},{"name":"seek","description":"Move the playhead to a time (seconds). Read-only — no batch needed.","inputSchema":{"type":"object","properties":{"time":{"type":"number"}},"required":["time"]},"ipc":true},{"name":"play","description":"Start playback from the current playhead position.","inputSchema":{"type":"object","properties":{}},"ipc":true},{"name":"pause","description":"Pause playback.","inputSchema":{"type":"object","properties":{}},"ipc":true},{"name":"save_project","description":"Save the project to disk as a .pms file. Always use the .pms extension — the UI file picker filters by *.pms, so any other extension (.pmsproj, .json, etc.) produces a file the user can't reopen from the app. If path is omitted, saves to the last-used path. Returns the path written. No batch needed.","inputSchema":{"type":"object","properties":{"path":{"type":"string","description":"Absolute path ending in .pms"}}},"ipc":true},{"name":"load_project","description":"Load a .pms project file, replacing the current project.","inputSchema":{"type":"object","properties":{"path":{"type":"string","description":"Absolute path to a .pms file"}},"required":["path"]},"ipc":true},{"name":"add_multifx_brick","description":"Add an ordered chain of FX sub-effects as one brick. This is THE way to layer effects over the same time range: FX bricks cannot overlap each other on a track (such calls are rejected), so stacked effects must be one MultiFX chain.\n\nSame-track as a video clip = glass mode (affects that clip only). Separate FX track = global (affects all layers below).\n\neffects[]: {fx_type, rel_start (0), rel_end (0=brick end), params, body_fx_type (if fx_type='body_fx')}\nbody_fx constraint: must be glass mode (same track as video clip).","inputSchema":{"type":"object","properties":{"track":{"type":"integer"},"track_name":{"type":"string","description":"Track name (alternative to track index)"},"start":{"type":"number"},"end":{"type":"number"},"effects":{"type":"array","description":"Ordered list of sub-effects","items":{"type":"object","properties":{"fx_type":{"type":"string","description":"Any fx_type from add_effect_brick, or 'body_fx'"},"body_fx_type":{"type":"string","description":"Required when fx_type is 'body_fx'"},"rel_start":{"type":"number","default":0},"rel_end":{"type":"number","default":0,"description":"0 = until brick end"},"params":{"type":"object"}},"required":["fx_type"]}}},"required":["start","end"]},"ipc":true},{"name":"rename_track","description":"Rename a track.","inputSchema":{"type":"object","properties":{"quiet":{"type":"boolean","description":"Return a small ack instead of the full project state (big token saver — use unless you need to re-read state)"},"track":{"type":"integer"},"track_name":{"type":"string","description":"Track name to look up (alternative to track index)"},"name":{"type":"string","description":"New name to assign"}},"required":["name"]},"ipc":true},{"name":"add_effect_brick","description":"Add a standalone FX brick to a track. Affects everything below on the timeline (or only the sibling video clip if on the same track — glass mode).\n\nFX bricks cannot overlap other FX bricks on a track — the call fails. To layer several effects over the same time range use one add_multifx_brick chain; overlapping a video/text clip (glass mode) is fine.\n\nfx_type — use the exact snake_case name. All params are floats. 'body_fx' is NOT valid here — use add_body_fx_brick instead.\n\nBASIC: grade (brightness,contrast,saturation,hue) | blur (blur) | vignette (vignette) | glitch (glitch_chroma 0-20,glitch_jitter,glitch_corruption,glitch_corruption_bleed) | zoom_punch (zoom_strength,zoom_decay,zoom_shake) | light_leak (leak_intensity,leak_speed) | vhs (vhs_noise,vhs_bleed,vhs_tracking) | datamosh (datamosh_intensity,datamosh_spread) | chroma_key (chroma_key_r/g/b,chroma_key_threshold,chroma_key_softness) | lut (no params—set lut_path via set_clip_prop)\n\nGLITCH: pixelate (amount,size) | chromatic_aberration (amount) | holographic (amount,speed) | rgb_split (amount,intensity,speed) | glitch_block (amount,intensity,speed) | pixel_sort (amount,threshold,intensity,direction) | double_ghost (amount,offset,opacity,angle) | vhs_dropout (amount,density,speed) | bit_crush (amount,levels,dither) | tv_static (amount,intensity,color_mix) | dither_bayer (amount,levels,scale,color) | interlace_glitch (amount,intensity,speed) | digital_noise (amount,intensity,color_sep,luma_bias) | scanline_color (amount,line_width,intensity,rgb_sep) | data_corrupt (amount,density,block_size,intensity) | pixel_mosaic (amount,block_size,color_steps) | rgb_split_wave (amount,amplitude,frequency,speed) | glitch (amount,glitch_chroma,glitch_jitter,glitch_corruption,glitch_corruption_bleed) | datamosh (amount,datamosh_intensity,datamosh_spread)\nFILM: film_grain (amount,intensity,size) | old_film (amount,sepia,scratch,flicker) | film_burn (amount,intensity,speed,edge) | daguerreotype (amount,tone,vignette,scratch) | super8_film (amount,grain,gate,fade) | vintage_negative (amount,orange_mask,contrast,grain) | film_halation (amount,threshold,radius,red_shift) | double_exposure (amount,offset_x,offset_y,scale2,desaturate2,opacity) | vignette (amount,vignette) | vhs (amount,vhs_noise,vhs_bleed,vhs_tracking)\nCOLOR: duotone (amount,shadow_r,shadow_g,shadow_b,highlight_r,highlight_g,highlight_b) | thermal (amount) | night_vision (amount,noise,gain) | posterize (amount,levels) | bleach_bypass (amount) | color_burn (amount,hue) | lomo (amount,vignette,saturation,fade) | cyberpunk_grade (amount,shadow_teal,hi_orange,contrast) | solarize (amount,threshold) | x_ray (amount,contrast,blue_tint) | miami_vice (amount,saturation) | horror_grade (amount,desat,red,crush) | split_toning (amount,shadow_hue,hi_hue) | desert_gold (amount,warmth,fade,haze) | gradient_map (amount,hue1,hue2) | cross_process (amount,contrast) | technicolor (amount,saturation,contrast,warmth) | kodachrome (amount,saturation,reds,shadows) | sepia_rich (amount,vignette,contrast) | color_dodge (amount,intensity,hue,glow) | infrared_film (amount,channel_mix,glow,contrast) | thermal_map (amount,cold_hue,hot_hue,contrast,scanlines) | golden_hour (amount,warmth,glow_str,shadow_lift,vignette) | zone_system_bw (amount,zones,contrast,grain,paper_white) | insta_2016 (amount,fade,pop,warmth) | grade (amount,brightness,contrast,saturation,hue)\nLIGHT: neon_glow (amount,width) | anamorphic_streak (amount,threshold,length,intensity) | starburst_spike (amount,threshold,length,rays) | god_rays (amount,intensity,decay,cx,cy) | aurora_borealis (amount,intensity,speed,color_shift) | bokeh_dream (amount,radius,threshold,intensity) | prism_disperse (amount,spread,intensity) | neon_edge_glow (amount,threshold,glow,hue) | fire_edge (amount,intensity,speed,height) | ice_crystal (amount,scale,refract,tint) | neon_sign (amount,edge_str,glow_radius,hue_shift,bg_darken) | glitter_dust (amount,density,size,sparkle,color_var) | light_leak (amount,leak_intensity,leak_speed)\nWARP: fisheye (amount) | twirl (amount,radius) | ripple (amount,frequency,amplitude,speed) | wave_warp (amount,freq_x,freq_y,amplitude,speed) | kaleidoscope (amount,segments,rotation,zoom) | heat_haze (amount,intensity,speed) | barrel_warp (amount,k1,k2,scale) | frosted_glass (amount,blur,noise,tint) | mirror_fold (amount,axis,vertical) | vortex_distort (amount,scale,speed) | tilt_shift (amount,focus_y,focus_band,blur_radius,saturation) | raindrop_refract (amount,density,size,refract_str) | mirror_tunnel (amount,depth,rotation,zoom) | liquid_chrome (amount,flow,metallic,tint_r,tint_g,tint_b)\nPATTERN: scanlines (amount,density) | halftone (amount,size) | crt (amount,curvature,glow) | matrix_rain (amount,density,speed,green_mix) | comic_dots (amount,dot_size,ink_threshold,color_levels) | crosshatch (amount,density,thickness,angle) | plasma_field (amount,scale,speed,intensity) | laser_grid (amount,grid_size,hue,intensity) | crt_barrel (amount,distort,corner_dark,rgb_shift,scanline) | contour_map (amount,levels,line_width,line_hue,fill_sat) | ascii_art (amount,char_size,fg_r,fg_g,fg_b,bg_dark) | dna_helix (amount,grid_scale,wave_amp,line_width,hue,bg_darken)\nMOTION: breathe (amount,breathe_rate,warp_strength,color_speed,chroma_split,complexity) | zoom_blur_rad (amount,intensity,cx,cy) | spin_blur (amount,angle) | echo_trails (amount,offset,fade,angle) | long_exposure (amount,threshold,trail,glow) | ken_burns (amount,start_scale,end_scale,start_x,start_y,end_x,end_y) | cam_shake (amount,intensity,speed)\nART: sketch (amount,invert) | oil_paint (amount,radius,sharpness) | stained_glass (amount,cell_size,border,saturation) | watercolor (amount,bleeding,paper,saturation) | emboss_relief (amount,angle,colorize) | pointillist (amount,dot_size,scatter) | warhol_pop (amount,levels,hue_shift,saturation) | risograph (amount,hue1,hue2,dot_size,misreg,paper) | pencil_sketch (amount,line_str,paper_tone,hatching)\nBEAUTY: skin_smooth (amount,radius,tone) | glow_up (amount,glow,warmth,brighten) | retro_beauty (amount,glow,fade,blush) | glass_skin (amount,radius,gloss)\nTOOLS: greenscreen (amount,key_r,key_g,key_b,similarity,smoothness,spill) | blur (amount,blur)\nMAKEUP: porcelain_skin (amount,smooth,brighten,warmth) | blush_doll (amount,blush,smooth,tint) | honey_glow (amount,glow,warmth,lift) | soft_glam (amount,glam,split,sparkle)\nTRIPPY: acid_trip (amount,trip,speed,wobble) | liquid_marble (amount,flow,scale,speed) | fractal_mirror (amount,folds,drift,zoom) | breathe_warp (amount,breathe,rate,chroma) | melt_drip (amount,melt,drip,haze)\nCYBERPUNK: neon_city (amount,neon,scanline,streak) | chrome_pulse (amount,chrome,pulse,edge) | hud_glitch (amount,hud,dropout,tint) | night_drive (amount,night,sodium,flare)\nCHROMA: chroma_key (amount,chroma_key_r,chroma_key_g,chroma_key_b,chroma_key_threshold,chroma_key_softness) | chroma_melt (amount,chroma_melt_r,chroma_melt_g,chroma_melt_b,chroma_melt_threshold,chroma_melt_persist) | chroma_echo (amount,chroma_echo_r,chroma_echo_g,chroma_echo_b,chroma_echo_threshold,chroma_echo_persist) | chroma_frame (amount,chroma_frame_r,chroma_frame_g,chroma_frame_b,chroma_frame_threshold,chroma_frame_taps,chroma_frame_spacing,chroma_frame_falloff)","inputSchema":{"type":"object","properties":{"track":{"type":"integer"},"track_name":{"type":"string","description":"Track name (alternative to track index)"},"fx_type":{"type":"string","description":"Snake_case FX type name (see description)"},"start":{"type":"number"},"end":{"type":"number"},"params":{"type":"object","description":"Effect-specific parameter values by name (see description)"}},"required":["fx_type","start","end"]},"ipc":true},{"name":"analyze_audio","description":"Run beat/RMS analysis on an audio file. Blocks until complete — returns {status: 'done', bpm, duration, beats, rms} when finished. No polling needed.","inputSchema":{"type":"object","properties":{"path":{"type":"string","description":"Absolute path to audio file"}},"required":["path"]},"ipc":true},{"name":"get_audio_analysis","description":"Poll beat/RMS analysis started by analyze_audio. Returns {status: 'idle'|'running'|'done'|'error', bpm?, duration?, beats?, rms?}. Poll every 2s until status='done'.","inputSchema":{"type":"object","properties":{}},"ipc":true},{"name":"find_audio_cue","description":"Find a beat-aligned timestamp matching a description ('first drop', 'chorus', 'outro', etc.).\nRequires: get_audio_analysis status='done' (call analyze_audio first, then poll).\nReturns: source_timestamp, bpm, duration, reasoning, alternatives. Audio positioning: clip start = -source_timestamp, end = video_duration - source_timestamp.","inputSchema":{"type":"object","properties":{"path":{"type":"string","description":"Absolute path to the audio file"},"description":{"type":"string","description":"What you're looking for"},"clip_duration":{"type":"number","description":"Clip length in seconds (optional, for fit check)"}},"required":["path","description"]},"ipc":false},{"name":"describe_video","description":"Start local scene analysis: extract keyframes at scene changes and caption each with the on-device Moondream2 model. Returns {status:'started'}, or {status:'cached'} when a fresh sidecar already exists (then get_video_description returns immediately). Poll get_video_description every ~10s — captioning costs about 10 s per scene on CPU, so long videos take minutes. Results are cached in <video>.pms_scene.json; pass force=true to recompute. Vision models ship with the release install.\n\nUse this to map a WHOLE video (summaries, find_video_moment scoring) — or when you have no vision capability of your own.\n\nBATCH (preferred for many clips): pass paths=[...] (up to 64) to caption a whole set in ONE call — don't loop describe_video per file. Then a single get_video_description returns {results:[{path, frames}]} for all of them (cached sidecars are reused, so re-runs are instant). Captioning is CPU-bound and runs sequentially internally, but you only spend ONE describe + ONE poll.\n\nTEXT-MODE CONTACT SHEET: pass times=[...] (max 48) to caption exactly those timestamps instead of auto-detected scenes — e.g. to verify segment boundaries from detect_screen_activity without vision. Custom-times runs skip the sidecar cache. Vision-capable agents should prefer make_contact_sheet (one image, no ~10s-per-frame captioning cost).\n\nIF you have Bash + Read tools and native vision, sampling stills yourself is faster for spot checks:\n  ffmpeg -y -ss <t> -i <path> -vframes 1 -vf scale=480:-1 /tmp/still.jpg, then Read it.\nOne still is never enough to judge a video — the first frame may be a black intro or a transition. Sample ~5 spread across the duration (10%/30%/50%/70%/90%), then binary-search a window when hunting a specific moment.","inputSchema":{"type":"object","properties":{"path":{"type":"string","description":"Absolute path to one video file"},"paths":{"type":"array","items":{"type":"string"},"description":"Batch: caption many videos in one call (up to 64). Use instead of looping per file."},"force":{"type":"boolean","description":"Recompute even if a cached sidecar exists"},"times":{"type":"array","items":{"type":"number"},"description":"Caption exactly these source times in seconds (max 48) instead of auto-detected scenes"}}},"ipc":true},{"name":"get_video_description","description":"Poll scene analysis started by describe_video (blocks internally until done — call ONCE, not in a loop). Single run → {status, frames:[{timestamp, description}], capped}. Batch run (describe_video paths=[...]) → {status, results:[{path, frames}]} for every video. Pass frames to find_video_moment to score against a query, or scan them yourself.","inputSchema":{"type":"object","properties":{}},"ipc":true},{"name":"find_video_moment","description":"Find the best-matching moment in a video by visual content. Scores the scene captions from describe_video against the query — run describe_video first (this tool tells you if the sidecar is missing). Returns ranked {timestamp, description, score} candidates.\n\nAgents with Bash + Read and native vision can alternatively sample stills around candidate timestamps to verify: ffmpeg -y -ss <t> -i <path> -vframes 1 /tmp/still_<t>.jpg, then Read it.","inputSchema":{"type":"object","properties":{"path":{"type":"string","description":"Absolute path to the video file"},"query":{"type":"string","description":"Natural-language description of the moment"}},"required":["path","query"]},"ipc":false},{"name":"find_and_add_clip","description":"Find a specific spoken moment in a media file and add it to the timeline. Does windowed speech-to-text search — chunk size is calculated from the file length (clamp(duration/4, 90s, 300s)) with 15% overlap — stops as soon as the match is found. Much faster than trigger_pipeline on long files.\n\nWORKS ON AUDIO-ONLY FILES TOO (FLAC, MP3, WAV, etc.) — not just video. This means you can locate an exact timestamp in a song or podcast without running the full pipeline. Useful for finding where a lyric or phrase occurs so you can trim the project to that point before generating typography.\n\nFOR LYRIC VIDEOS / SCOPED SECTIONS — use this BEFORE trigger_pipeline when the user wants only a section of a song. The canonical flow is:\n  1. find_and_add_clip(path=full_file, query='start phrase')  → start timestamp\n  2. find_and_add_clip(path=full_file, query='end phrase')    → end timestamp\n  3. add_track + add_clip(audio, full_file), then trim_clip the brick to [start, end]\n  4. trigger_pipeline on that brick — it transcribes only the trimmed region\n  5. poll get_pipeline_status until stage='done', then set_typography_preset(preset='flash')\nDO NOT skip step (2): you need both timestamps to bound the section; find_and_add_clip's auto-added clip only covers a small window around a single matched phrase.\n\nCHUNK-STRADDLING PHRASES are handled internally: when a partial match lands at the trailing edge of a search chunk, the scanner extends into the next chunk before reporting found, so result.end reflects the real phrase end (not the chunk boundary). Same goes for queries whose match lives past an existing cached transcript — the cache is extended automatically.\n\nBlocks until the match is found — no polling needed. Returns status=found.\n\nAlways returns extracted=true with a ready-to-use dst file at result.dst — extraction is handled internally.\n\nresult includes in_point = offset into dst where your content starts.\n\nMATCH QUALITY: result includes score (0-1, fraction of query words found) and partial_match (true when score<1.0 OR the located span is wider than ~1.5s/word). When partial_match=true, treat start/end as APPROXIMATE — the located span may include leading/trailing context rather than just the query phrase. Do not derive exact word timestamps from a partial match; re-run with a corrected query or use trigger_pipeline + get_transcript on the matched segment for word-level alignment.\n\nadd_clip: track=<target>, type=video, text=result.dst, start=0, end=result.clip_duration, in_point=result.in_point","inputSchema":{"type":"object","properties":{"path":{"type":"string","description":"Absolute path to the media file (video or audio)"},"query":{"type":"string","description":"What to search for in the transcript"},"track":{"type":"integer","description":"Track to add the clip to (default 0)"},"padding":{"type":"number","description":"Seconds of context before/after match (default 5.0)"}},"required":["path","query"]},"ipc":false},{"name":"get_transcript","description":"Return the word-level transcript produced by the transcription pipeline. Returns {status: 'idle'|'ready'|'error', words?: [{word, start, end}], path?}. Word timestamps are source-file-relative seconds.\n\nBy default reads the project's current transcript. Pass `path` to inspect the cached transcript of any previously-transcribed file (e.g. the full song before you sectioned it) without changing project state.\n\nSTATUS IDLE — what to do next depends on your task:\n  Finding a specific moment/phrase → use find_and_add_clip (windowed, stops early, MUCH faster).\n    DO NOT run trigger_pipeline just to search.\n  Generating full subtitles/karaoke for a clip already on the timeline → use trigger_pipeline.","inputSchema":{"type":"object","properties":{"path":{"type":"string","description":"Optional: read the cached transcript for this file path instead of the project's current one. Read-only — does not change project state."}}},"ipc":true},{"name":"set_transcript","description":"Install a custom word-level transcript for the project's current audio. Writes the canonical cache JSON next to the audio file and reloads the in-memory word cache so set_typography_preset uses your words immediately.\n\nUSE THIS WHEN:\n  - whisper.cpp on the current audio produced wrong / sparse word timings and you want to override with hand-edited words.\n  - You computed words from another source (different transcriber, manual alignment) and want the managed Lyrics path to use them.\n\nAfter this call, set_typography_preset(preset='flash'|...) will lay lyric clips at the timings you provided. words: [{word: str, start: float, end: float}, ...]","inputSchema":{"type":"object","properties":{"words":{"type":"array","description":"Word list to install as the project transcript","items":{"type":"object","properties":{"word":{"type":"string"},"start":{"type":"number","description":"Seconds, audio-relative"},"end":{"type":"number","description":"Seconds, audio-relative"}},"required":["word","start","end"]}}},"required":["words"]},"ipc":true},{"name":"read_transcript_context","description":"Read words from the saved transcript for a source video file around a specific timestamp. Use after find_and_add_clip to find exact speaker boundaries, sentence starts, etc.\n\nReturns {utterances, words}.\nutterances: words grouped by pauses — each is {start, end, gap_before, text}. gap_before > 0 marks a likely speaker change (default threshold 0.8s). Use utterances to read the transcript; use words only when you need per-word timestamps.\nwords: raw [{word, start, end}] for the window [time-before, time+after].","inputSchema":{"type":"object","properties":{"path":{"type":"string","description":"Absolute path to the source video file"},"time":{"type":"number","description":"Center timestamp in source-file seconds"},"before":{"type":"number","description":"Seconds before 'time' to include (default 30)"},"after":{"type":"number","description":"Seconds after 'time' to include (default 60)"},"gap_threshold":{"type":"number","description":"Pause length in seconds that splits utterances (default 0.8)"}},"required":["path","time"]},"ipc":false},{"name":"search_transcript","description":"Search the transcript for ALL occurrences of a phrase. Returns every match with source-file timestamps — use this before any phrase-based cut to see if the phrase appears more than once. Timestamps are source-file seconds (subtract clip in_point to get timeline position). Requires trigger_pipeline or find_and_add_clip to have run first.","inputSchema":{"type":"object","properties":{"phrase":{"type":"string","description":"The phrase to search for"},"path":{"type":"string","description":"Source video path (defaults to project audio_path)"}},"required":["phrase"]},"ipc":true},{"name":"cut_at_phrase","description":"Trim a clip to end (or start) right at a phrase. Collapses transcript lookup + trim into one call.\n\nside='after' (default): trims clip end to just after the last word of the phrase.\nside='before': trims clip start to just before the first word.\n\nIf the phrase appears more than once, returns all matches and does NOT trim — re-call with occurrence=N (0-indexed) to select which one.\n\nRequires a ready transcript. To get one without running the full pipeline:\n  use find_and_add_clip first (windowed search, much faster than trigger_pipeline).\nOnly use trigger_pipeline if you need a full transcript for subtitles/karaoke.","inputSchema":{"type":"object","properties":{"track":{"type":"integer"},"clip":{"type":"integer"},"phrase":{"type":"string"},"side":{"type":"string","enum":["after","before"],"default":"after"},"occurrence":{"type":"integer","description":"0-indexed match to use when multiple exist"}},"required":["track","clip","phrase"]},"ipc":false},{"name":"remove_silence","description":"Automatically detect and remove silent segments from a video or audio clip. Uses per-second RMS energy (1-second resolution — pauses shorter than ~0.5s may not be detected). Works back-to-front so clip indices stay valid. Returns {removed: [{start, end, duration}, ...], count}.\n\nTypical threshold: 0.04–0.08 for speech; min_duration: 0.5–1.0s; padding: 0.1–0.2s to avoid clipping words.","inputSchema":{"type":"object","properties":{"track":{"type":"integer","description":"Track index"},"clip":{"type":"integer","description":"Clip index within the track"},"threshold":{"type":"number","description":"RMS below this = silence (0–1). Default 0.05"},"min_duration":{"type":"number","description":"Minimum silence length in seconds to remove. Default 0.5"},"padding":{"type":"number","description":"Seconds of audio to preserve on each side of a cut. Default 0.15"}},"required":["track","clip"]},"ipc":false},{"name":"cut_filler_words","description":"Remove filler words ('um', 'uh', 'like', etc.) from a clip using the word-level transcript. Run trigger_pipeline and wait for it to finish first. Use dry_run=true to preview matches before committing. Returns {removed: [{word, start, end}, ...], count} or {matches: [...]} in dry-run mode.","inputSchema":{"type":"object","properties":{"track":{"type":"integer","description":"Track index"},"clip":{"type":"integer","description":"Clip index within the track"},"words":{"type":"array","items":{"type":"string"},"description":"Filler words/phrases to remove. Default: [\"um\",\"uh\",\"uh-huh\",\"like\",\"you know\",\"kind of\",\"sort of\",\"basically\",\"literally\",\"actually\",\"right\",\"okay\"]"},"padding":{"type":"number","description":"Seconds to trim from each side to avoid clipping. Default 0.04"},"dry_run":{"type":"boolean","description":"If true, return matches without making cuts. Default false"}},"required":["track","clip"]},"ipc":false},{"name":"apply_multicam_cuts","description":"Given multiple camera-angle clips on parallel tracks, apply a cut list that keeps only the selected camera in each time window. All other camera-track clips in that window are deleted. Non-camera tracks (captions, FX, etc.) are left untouched.\n\nPrecondition: each camera track has a clip covering the full range. Returns {windows: [{start, end, track}], deleted_count}.\n\nExample: cuts=[{time:0,track:2},{time:8.3,track:3}], camera_tracks=[2,3]","inputSchema":{"type":"object","properties":{"cuts":{"type":"array","items":{"type":"object","properties":{"time":{"type":"number","description":"Timeline time (seconds) where this camera takes over"},"track":{"type":"integer","description":"Track index to use from this time onward"}},"required":["time","track"]},"description":"Ordered list of camera switches. Must start at or before the earliest clip start."},"camera_tracks":{"type":"array","items":{"type":"integer"},"description":"Which track indices are camera tracks. Only these will have segments deleted."}},"required":["cuts","camera_tracks"]},"ipc":false},{"name":"validate_glsl","description":"Test-compile a GLSL fragment shader body without registering it as a runtime effect. Returns {ok: bool, error?: string}. Useful before writing a shader to disk. No batch needed.","inputSchema":{"type":"object","properties":{"glsl":{"type":"string"},"params":{"type":"array","items":{"type":"object","properties":{"name":{"type":"string"},"label":{"type":"string"},"min":{"type":"number"},"max":{"type":"number"},"default":{"type":"number"}},"required":["name"]}}},"required":["glsl"]},"ipc":true},{"name":"add_chapter_marker","description":"Add a chapter/section marker at a specific timeline position. Markers appear as colored vertical lines with labels in the timeline ruler. They are sorted by time automatically. Returns {index} of the inserted marker.","inputSchema":{"type":"object","properties":{"time":{"type":"number","description":"Timeline position in seconds"},"label":{"type":"string","description":"Chapter label (short text displayed in ruler)"},"color":{"type":"string","description":"Hex color e.g. '#4A90E2' (optional, defaults to cornflower blue)"}},"required":["time","label"]},"ipc":false},{"name":"remove_chapter_marker","description":"Remove a chapter marker by its index (from get_project markers array or add_chapter_marker response).","inputSchema":{"type":"object","properties":{"index":{"type":"integer","description":"Marker index to remove"}},"required":["index"]},"ipc":false},{"name":"set_loop_region","description":"Arm the transport loop and optionally set the loop brace region. Playback then cycles seamlessly over [start, end] (or the whole timeline if start/end are omitted) instead of stopping at the end. The brace is shown in the timeline ruler and the green Loop button lights up. Pass enabled=false to disarm looping. Returns {loop_play, loop_in, loop_out}.","inputSchema":{"type":"object","properties":{"start":{"type":"number","description":"Loop region start in seconds (omit for whole timeline)"},"end":{"type":"number","description":"Loop region end in seconds (must be > start)"},"enabled":{"type":"boolean","description":"Arm (true, default) or disarm (false) the loop"}}},"ipc":true},{"name":"generate_chapters","description":"Auto-generate chapter markers from the transcript by finding natural pause points. Call get_transcript first — this tool requires a ready transcript.\n\nTwo modes (mutually exclusive):\n  num_chapters: place exactly N chapters by splitting at the N-1 longest pauses\n  min_pause_seconds: place a chapter wherever a pause exceeds this threshold (default 3.0s)\n\nAlways adds a first chapter at t=0 labeled from the first few words. Returns {chapters: [{time, label}]}.","inputSchema":{"type":"object","properties":{"num_chapters":{"type":"integer","description":"Exact number of chapters to generate (overrides min_pause_seconds)"},"min_pause_seconds":{"type":"number","description":"Minimum gap in seconds to trigger a chapter boundary (default 3.0)"}}},"ipc":false},{"name":"add_callout","description":"Add a callout text overlay — a positioned text box with optional arrow pointing at a canvas location. Good for labelling objects, people, or actions on screen.\n\nPosition (pos_x, pos_y) and arrow target (arrow_x, arrow_y) are canvas fractions: 0,0 = top-left, 1,1 = bottom-right, 0.5,0.5 = center.\n\ncallout_style: 0=plain box, 1=box (default), 2=pill (high corner radius), 3=speech bubble\n\nReturns {track, clip} indices of the created text clip.","inputSchema":{"type":"object","properties":{"track":{"type":"integer","description":"Track index to place the callout on"},"start":{"type":"number","description":"Start time in seconds"},"end":{"type":"number","description":"End time in seconds"},"text":{"type":"string","description":"Callout label text"},"pos_x":{"type":"number","description":"Canvas X position of the text box (0–1)"},"pos_y":{"type":"number","description":"Canvas Y position of the text box (0–1)"},"arrow_x":{"type":"number","description":"Canvas X of the arrow tip target (0–1). Enables arrow if provided."},"arrow_y":{"type":"number","description":"Canvas Y of the arrow tip target (0–1). Enables arrow if provided."},"callout_style":{"type":"integer","description":"Box style: 0=plain, 1=box, 2=pill, 3=speech bubble (default 1)"},"font_size":{"type":"number","description":"Font size as fraction of canvas height (default 0.04)"},"bg_color":{"type":"array","description":"[r,g,b,a] background color 0–1 (default semi-transparent dark)"}},"required":["track","start","end","text","pos_x","pos_y"]},"ipc":false},{"name":"add_shape","description":"Add a shape clip (ClipType::Shape) to a track. Shapes are content layers that composite like text/background, NOT FX bricks. The shape is placed at canvas center by default; use set_clip_prop to move/scale/rotate it, set_clip_keyframes to animate the transform, set_shape_keyframes to morph the path over time, and shape_stroke_length keyframes for draw-on reveal.\n\npreset: circle | square | triangle | star | heart | polygon | hexagon | burst | arrow | lightning | diamond | cross\nparams (preset-specific): star/burst=[point_count, inner_ratio], polygon=[sides], arrow=[stem_frac, head_frac], lightning=[jag_amplitude]. Others take no params.\n\nReturns {track, clip, preset}.","inputSchema":{"type":"object","properties":{"track":{"type":["integer","string"],"description":"Track index or name"},"start":{"type":"number","description":"Start time in seconds"},"end":{"type":"number","description":"End time in seconds (default start+3)"},"preset":{"type":"string","description":"Shape preset name (default 'circle')"},"params":{"type":"array","description":"Preset-specific params (floats)"}},"required":["track","start"]},"ipc":true},{"name":"set_shape_path","description":"Replace the base path of a shape clip with a custom path (freehand or edited). Points are in local [0,1]² space (the path's bbox maps to the unit square, then the clip transform places it on the canvas). Each point: {x, y, w?} where w is per-point stroke width (fraction canvas height, default 0.008). closed=true enables fill + connects last point back to first.","inputSchema":{"type":"object","properties":{"track":{"type":"integer"},"clip":{"type":"integer"},"points":{"type":"array","description":"Array of {x, y, w?} in 0..1 local space"},"closed":{"type":"boolean","description":"Close the path (enables fill)"}},"required":["track","clip","points"]},"ipc":true},{"name":"set_shape_style","description":"Set visual style on a shape clip. All fields optional — only provided fields update. Colors are [r,g,b,a] 0..1. grad_mode: 0=none 1=linear 2=radial 3=hue-cycle. stroke_width and glow_radius are fractions of canvas height.","inputSchema":{"type":"object","properties":{"track":{"type":"integer"},"clip":{"type":"integer"},"fill_on":{"type":"boolean"},"fill_col":{"type":"array"},"stroke_on":{"type":"boolean"},"stroke_col":{"type":"array"},"stroke_width":{"type":"number"},"grad_mode":{"type":"integer"},"grad_col2":{"type":"array"},"grad_angle":{"type":"number"},"glow_on":{"type":"boolean"},"glow_col":{"type":"array"},"glow_radius":{"type":"number"},"glow_intensity":{"type":"number"}},"required":["track","clip"]},"ipc":true},{"name":"set_shape_keyframes","description":"Replace the path-morph keyframe track on a shape clip. Each key is a full path snapshot at time t (seconds relative to clip start). The engine resamples adjacent keys to a common point count and lerps each point (x, y, width) with the same easing curves as scalar keyframes. Pass an empty keys array to clear morph animation. interp: linear | ease_in | ease_out | ease_both | hold.","inputSchema":{"type":"object","properties":{"track":{"type":"integer"},"clip":{"type":"integer"},"keys":{"type":"array","description":"Array of {t, points, closed?, interp?}"}},"required":["track","clip","keys"]},"ipc":true},{"name":"get_shape_path","description":"Return the effective path of a shape clip at time t (default: current playhead). When path-morph keyframes exist, returns the interpolated path at t; otherwise the base path. Points are {x, y, w} in local [0,1]² space. Also returns key_count.","inputSchema":{"type":"object","properties":{"track":{"type":"integer"},"clip":{"type":"integer"},"t":{"type":"number","description":"Time in seconds (default playhead)"}},"required":["track","clip"]},"ipc":true},{"name":"add_body_fx_brick","description":"Add a Body FX solid brick to a track. The brick applies a body/silhouette-based visual effect (e.g. neon outline, depth blur, glitch, retro TV) to the composited frame below it — it is NOT a glass effect and does NOT attach to a specific video clip.\n\nAfter adding the brick, call process_body_fx_masks to compute the body masks from the video clip(s) on tracks below. Processing is async; poll get_project or get_pipeline_status to monitor progress.\n\nfx_type options — pass the exact display name (space-separated Title Case, as listed):\n  Mask:         Remove Background\n  Retro / 80s:  Neon Outline | VHS Body | Scanlines | Chromatic Body | Retrowave | TV Static Bg | Arcade | Film Grain Body\n  Depth/Focus:  Depth Blur | Tilt-Shift Bg | Spotlight | Fog Bg | Bokeh Bg\n  Glitch:       Glitch Body | Glitch Bg | Split Reality | Data Corruption | Signal Loss Bg | Chromafall\n  Color:        Color Isolation | Invert Bg | Duotone Body | Duotone Bg | Thermal Body | X-Ray\n  Light/Glow:   Electric Aura | Rim Light | God Rays | Halo | Bloom Body | Bioluminescent\n  Abstract:     Hologram | Matrix Rain Bg | Body Mosaic | Wireframe Bg | Vaporwave\n  Party:        Strobe Bg | Disco Body | UV Paint | Fire Aura\nNames are case-sensitive AND space-separated — these are different effects from the snake_case shader names used by add_effect_brick (e.g. BodyFX 'Scanlines' uses body masks; add_effect_brick fx_type='scanlines' is a fullscreen shader). If unsure, use 'Neon Outline' or 'Depth Blur'.\n\nReturns {track, clip} of the created brick.","inputSchema":{"type":"object","properties":{"track":{"type":"integer","description":"Track index for the brick (should be above video tracks)"},"start":{"type":"number","description":"Start time in seconds"},"end":{"type":"number","description":"End time in seconds"},"fx_type":{"type":"string","description":"BodyFX effect name (see list above)"},"amount":{"type":"number","description":"Blend strength 0–1 (default 0.8)"},"param_0":{"type":"number","description":"Effect-specific param 0 (optional)"},"param_1":{"type":"number","description":"Effect-specific param 1 (optional)"},"param_2":{"type":"number","description":"Effect-specific param 2 (optional)"},"param_3":{"type":"number","description":"Effect-specific param 3 (optional)"}},"required":["track","start","end"]},"ipc":false},{"name":"process_body_fx_masks","description":"Start body mask processing for a Body FX brick. This analyses the video clip(s) on tracks below the brick and writes body-segmentation masks for the brick's time range. Async — returns immediately; poll get_project for body_fx_mask_status ('Processing' → 'Ready'). Only needed once per brick; re-run if you extend the brick's right edge past the already-processed range.\n\nREQUIRES PROXY: the video clip's MJPEG proxy must be on disk before calling this. Newly-imported clips show instantly via direct decode but proxy generation runs in the background — this call fails with 'video proxy not ready yet' until the proxy finishes. Poll get_project for proxy_status on the source video clip and retry when it reports 'ready'.","inputSchema":{"type":"object","properties":{"track":{"type":"integer","description":"Track index of the BodyFX brick"},"clip":{"type":"integer","description":"Clip index of the BodyFX brick"}},"required":["track","clip"]},"ipc":false},{"name":"remove_background","description":"Remove the background from a video clip using RobustVideoMatting (RVM) alpha matting. Adds a 'Remove Background' body_fx brick on the same track as the video clip (mask processing starts automatically). Blocks until masks are ready. No batch needed.\n\nREQUIRES PROXY: fails with 'video proxy not ready yet' when the clip's MJPEG proxy hasn't finished transcoding. Newly-imported clips preview instantly via direct libav decode but bg_remove specifically reads from the proxy. Poll get_project for the source clip's proxy_status and retry when it reports 'ready'.","inputSchema":{"type":"object","properties":{"track":{"type":"integer","description":"Track index of the video clip"},"clip":{"type":"integer","description":"Clip index of the video clip"}},"required":["track","clip"]},"ipc":false},{"name":"set_format","description":"Set the project canvas format / aspect ratio. Three presets:\n  square     — 1:1   1080×1080  (Instagram square)\n  vertical   — 9:16  1080×1920  (TikTok / Reels / Shorts)\n  horizontal — 16:9  1920×1080  (YouTube / widescreen)\nNo batch needed.","inputSchema":{"type":"object","properties":{"format":{"type":"string","enum":["square","vertical","horizontal"],"description":"square=1:1, vertical=9:16, horizontal=16:9"}},"required":["format"]},"ipc":true},{"name":"take_snapshot","description":"Renders the canvas frame to PNG and returns the image inline so you can see it. Pass an optional time (seconds) to snap at that timestamp without seeking first. source='render' (default) re-renders the frame through the export pipeline — what an exported video will contain. source='canvas' captures the live preview rect from the app's framebuffer — the exact pixels the user is looking at (interactive scene compositor + text overlays). If the two disagree, the preview compositor and export renderer have diverged — capture both to diagnose which side is wrong. source='ui' captures the ENTIRE app window — timeline, panels, canvas, popups — use it to see the app state itself (e.g. verifying timeline markers, panel layouts, or what the user is describing) rather than the composition. Read-only — no batch needed.","inputSchema":{"type":"object","properties":{"time":{"type":"number","description":"Timeline position to snap (default: current playhead)"},"source":{"type":"string","enum":["render","canvas","ui"],"description":"render = export pipeline (default); canvas = live preview ground truth; ui = whole app window"}}},"ipc":true},{"name":"detect_screen_activity","description":"Scan a screen recording for visual activity, for planning retimes/cuts of technical footage. Runs server-side over the existing .pms_proxy.mjpeg + .idx seek table (sequential pass, never touches the original file) — the proxy must be ready (it generates automatically after add_clip; check proxy status if unsure). Computes per-frame mean absolute pixel diff (0-255 grayscale) inside one or more normalized screen regions and returns merged segments per region: [{t0, t1, state: 'active'|'idle', mean_diff}].\n\nPURELY MECHANICAL: the numbers say where pixels changed, nothing more. YOU interpret what active/idle means for this recording (e.g. 'terminal spinner = agent working', 'prompt box changing = user typing') — pick regions that make that interpretation unambiguous.\n\nregions: {name: [x0, y0, x1, y1]} normalized 0-1 (default {'frame': full}). Watching a small region (a spinner, a prompt box) is far more selective than whole-frame diff. threshold: mean-diff above this = active (default 1.5; raise for noisy video). min_segment: shorter state runs are absorbed into the previous segment (default 1.0 s) so blinking cursors don't fragment output. sample_fps: scan rate (default 3 — a 40-min recording scans in a few seconds). NOTE: diffs are between consecutive SAMPLES, so a higher sample_fps means smaller per-sample diffs against the same threshold — if you raise sample_fps, lower threshold proportionally (or keep both defaults).\n\nASYNC — returns immediately with {started}; poll get_activity_status every 2-3 s until state='done'. Progress also shows in the app UI. Typical flow: detect → interpret segments → begin_batch + split_clip + set_clip_prop (speed up to 100x) to retime the idle stretches.","inputSchema":{"type":"object","properties":{"path":{"type":"string","description":"Absolute path of the source video (proxy must exist)"},"regions":{"type":"object","description":"Named normalized rects {name: [x0,y0,x1,y1]}. Default: {'frame': [0,0,1,1]}","additionalProperties":{"type":"array","items":{"type":"number"},"minItems":4,"maxItems":4}},"threshold":{"type":"number","description":"Mean abs diff (0-255) above which a frame counts as active (default 1.5)"},"min_segment":{"type":"number","description":"Minimum segment duration in seconds (default 1.0)"},"sample_fps":{"type":"number","description":"Frames per second to sample (default 3)"}},"required":["path"]},"ipc":false},{"name":"get_activity_status","description":"Poll a detect_screen_activity job: {state: 'running'|'done'|'error', progress 0-1, result?} — result carries the per-region segment lists when done. Pass the same path; omit it to get the most recently started job. Read-only.","inputSchema":{"type":"object","properties":{"path":{"type":"string","description":"Source path passed to detect_screen_activity (optional)"}}},"ipc":false},{"name":"make_contact_sheet","description":"One tiled thumbnail grid with burned-in timestamps for a list of timeline times on a source file, returned inline — visually verify ambiguous segment boundaries (e.g. from detect_screen_activity) in ONE image call instead of N stills. Decodes from the proxy seek table when available (fast), falls back to ffmpeg on the original. Up to 48 times per call. Read-only.\n\nRequires vision: the result is an image. Text-only agents should use describe_video(times=[...]) instead — same idea, local captions as text.","inputSchema":{"type":"object","properties":{"path":{"type":"string","description":"Absolute path of the source video"},"times":{"type":"array","items":{"type":"number"},"description":"Source times in seconds, one tile per entry (max 48)"},"cols":{"type":"integer","description":"Grid columns (default 4)"}},"required":["path","times"]},"ipc":false},{"name":"verify_clips","description":"Seek to each time and snapshot to visually confirm clip content. Use after placing video clips from transcript timestamps — pass the midpoint of each clip. Returns [{time, path}] in order. Read-only — no batch needed.","inputSchema":{"type":"object","properties":{"times":{"type":"array","items":{"type":"number"},"description":"Timeline positions (seconds) to snapshot, one per clip to verify"}},"required":["times"]},"ipc":false},{"name":"add_audio_multifx_brick","description":"Add an Audio Multi-FX brick: an ordered chain of LIVE audio effects that auto-couples (1.5s weld timer skipped — couples immediately) to the best-overlapping audio content on the same track. Effects run live like a DAW insert chain: preview, monitor, and export all stream through the same DSP.\n\nAudio fx_types: audio_autotune (strength,speed,key,scale), audio_pitch (semitones), audio_formant (shift), audio_reverb (mix,size,damp), audio_delay (time,feedback,mix), audio_codec (bitrate crush). Video FX are rejected here; audio FX are rejected from the (video) multi-FX brick.","inputSchema":{"type":"object","properties":{"track":{"type":"integer"},"track_name":{"type":"string"},"start":{"type":"number"},"end":{"type":"number"},"effects":{"type":"array","items":{"type":"object","properties":{"fx_type":{"type":"string"},"rel_start":{"type":"number","default":0},"rel_end":{"type":"number","default":0},"params":{"type":"object"}},"required":["fx_type"]}}},"required":["start","end"]},"ipc":true},{"name":"decouple_fx_brick","description":"Decouple a welded (coupled) Multi-FX brick from its host content clip, turning it back into a free-floating glass brick at its current position. The UI equivalent is right-click → 'Decouple Multi FX brick' or the host clip's FX tab.","inputSchema":{"type":"object","properties":{"track":{"type":"integer"},"track_name":{"type":"string"},"clip":{"type":"integer","description":"Index of the coupled FX brick"}},"required":["clip"]},"ipc":true},{"name":"get_face_track","description":"Live face tracker state (camera mirror): lock validity, detector score, key landmark positions, worker flip/redetect counters, and (full:true) all 106 landmarks plus the mirror quad geometry — enough to predict overlay screen positions numerically. Face filters themselves are clip props: set_clip_prop face_filter (0=None 1=Pretty 2=BigEyes 3=TinyFace 4=BigMouth 5=Alien 6=Doggy) and face_filter_amt (0-1.5) on a video_record clip.","inputSchema":{"type":"object","properties":{"full":{"type":"boolean","description":"Include all 106 landmarks + mirror geometry"}}},"ipc":true},{"name":"select_clip","description":"Set the canvas selection — the clip whose transform handles (move/resize/rotate box) show on the preview. Pairs with get_canvas_geometry + ui_input. Omit 'clip' (or pass -1) to clear the selection.","inputSchema":{"type":"object","properties":{"track":{"type":"integer"},"track_name":{"type":"string"},"clip":{"type":"integer"}}},"ipc":true},{"name":"get_audio_perf","description":"Audio engine performance/latency readout: backend (pipewire native vs SDL), block size, measured input/output latency, xrun count, performance-mode state. Use when diagnosing monitoring latency or glitches.","inputSchema":{"type":"object","properties":{}},"ipc":true},{"name":"undo","description":"Undo the last edit. Returns updated project state so you can verify the revert. Read-only — no batch needed.","inputSchema":{"type":"object","properties":{}},"ipc":true},{"name":"redo","description":"Redo the last undone edit. Returns updated project state. Read-only — no batch needed.","inputSchema":{"type":"object","properties":{}},"ipc":true},{"name":"trim_all_to","description":"Trim every clip on every track so nothing extends past 'time'. Clips starting at or after 'time' are deleted; clips straddling 'time' are clamped. One undo step. No batch needed.","inputSchema":{"type":"object","properties":{"time":{"type":"number","description":"Maximum end time in seconds"}},"required":["time"]},"ipc":true},{"name":"make_section","description":"Crop the whole project to a [start, end] window and shift it to begin at 0 — the one-call way to turn a full song into just a section. Clips fully outside the window are dropped; straddlers are clamped to it; audio/video in_point advances by whatever is trimmed off the left so the source still plays the right span. Every kept clip moves by -start, so audio, video and lyric/subtitle tracks shift TOGETHER and stay in sync — no need to re-run set_typography_preset. One undo step.\n\nUSE THIS after deleting off-section clips: e.g. you kept the intro's lyrics/videos but the audio is still the full song — make_section(start, end) trims the audio to the section AND closes the leading gap in one shot. Times are seconds in the CURRENT timeline (pre-shift).","inputSchema":{"type":"object","properties":{"start":{"type":"number","description":"Section start in current-timeline seconds (becomes t=0)"},"end":{"type":"number","description":"Section end in current-timeline seconds"}},"required":["start","end"]},"ipc":true},{"name":"delete_clips_after","description":"Delete all clips on one track whose start >= time. One undo step. No batch needed.","inputSchema":{"type":"object","properties":{"track":{"type":"integer"},"track_name":{"type":"string","description":"Track name (alternative to track index)"},"time":{"type":"number","description":"Delete clips starting at or after this time (seconds)"}},"required":["time"]},"ipc":true},{"name":"delete_track","description":"Delete a whole track (and all its clips) by index or name. One undo step. No batch needed. To remove individual clips use delete_clip / delete_clips_after instead.","inputSchema":{"type":"object","properties":{"track":{"type":"integer"},"track_name":{"type":"string","description":"Track name (alternative to track index)"}}},"ipc":true},{"name":"set_clip_fx","description":"Set parameters on an FX brick attached to a clip. Use after adding an effect (add_effect_brick / add_multifx_brick) to tune it. amount is the master 0–1 strength; params is an object of named shader params (numbers only), e.g. {\"speed\": 1.5, \"scale\": 0.3}. Read the clip's current fx via get_project(verbose=true). No batch needed.","inputSchema":{"type":"object","properties":{"track":{"type":"integer"},"clip":{"type":"integer"},"fx_id":{"type":"string","description":"Effect id on the clip (from get_project verbose)"},"amount":{"type":"number","description":"Master strength 0–1"},"params":{"type":"object","description":"Named shader params → numeric values"}},"required":["track","clip","fx_id"]},"ipc":true},{"name":"get_chapter_markers","description":"Return all timeline markers (a.k.a. chapter/section markers): [{index, time, label, color}], sorted by time. Read-only — no batch needed. Pairs with add_chapter_marker / remove_chapter_marker.","inputSchema":{"type":"object","properties":{}},"ipc":false},{"name":"set_audio_path","description":"Set the project's master audio source (the file used for transcription and lyric alignment). Normally set automatically when you add the first audio clip — only call this to point the pipeline at a different file. No batch needed.","inputSchema":{"type":"object","properties":{"path":{"type":"string","description":"Absolute path to the audio/video file"}},"required":["path"]},"ipc":true},{"name":"collect_project","description":"Save the project as a self-contained folder: copy every referenced media original (clip sources, LUTs, master audio, bin) into a media/ folder beside the .pms and rewrite the references to the copies. Use for a portable backup or handoff. path is the destination .pms (a folder is created around it). No batch needed.","inputSchema":{"type":"object","properties":{"path":{"type":"string","description":"Destination .pms path (folder created around it)"}},"required":["path"]},"ipc":true}])PMSTOOLS";

